using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
using System.Drawing;

namespace ZoneSpawner {
 public static class SetupApplication {
  [STAThread] public static int Run(string root,string[] args){
   try{if(args.Contains("--install")){Console.SetOut(new StreamWriter(Console.OpenStandardOutput(),new System.Text.UTF8Encoding(false)){AutoFlush=true});Console.SetError(new StreamWriter(Console.OpenStandardError(),new System.Text.UTF8Encoding(false)){AutoFlush=true});}var profile=SetupProfile.Load(root);
    if(args.Contains("--install")){var options=new Dictionary<string,string>();for(int n=0;n<args.Length;n++){if(args[n]=="--install")continue;if(n+1>=args.Length||options.ContainsKey(args[n]))throw new ArgumentException("Некорректные параметры установки.");options.Add(args[n],args[++n]);}
     if(options.Keys.Any(k=>k!="--game"&&k!="--base"&&k!="--fix"))throw new ArgumentException("Неизвестный параметр установки.");string game,baseZip,fixZip;if(!options.TryGetValue("--game",out game)){var found=SteamDiscovery.Find();if(found.Count!=1)throw new IOException("Игра не определена однозначно. Запусти ZoneSpawner.Setup.exe или укажи --game.");game=found[0].Root;}
     SetupCore.VerifyGame(profile,game,true);if(!options.TryGetValue("--fix",out fixZip))fixZip=SetupCore.FindArchive(profile.FixHash,new[]{SetupCore.Cache,Path.Combine(root,"dependencies"),SteamDiscovery.Downloads()});
     if(fixZip==null)throw new IOException("Скачай фикс 1.2 с Nexus и выбери его в ZoneSpawner.Setup.exe.");if(!options.TryGetValue("--base",out baseZip))baseZip=SetupCore.DownloadBase(SetupCore.Cache,Console.WriteLine,CancellationToken.None).GetAwaiter().GetResult();SetupCore.Install(profile,game,baseZip,fixZip,Console.WriteLine,CancellationToken.None);return 0;
    }
    bool created;using(var mutex=new Mutex(true,"Local\\ZoneSpawnerSetup",out created)){if(!created){MessageBox.Show("Мастер установки уже открыт.");return 1;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var form=new SetupForm(profile))Application.Run(form);}return 0;
   }catch(Exception e){if(args.Contains("--install"))Console.Error.WriteLine(e.Message);else MessageBox.Show(e.Message,"Zone Spawner — установка",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}
  }
 }
 internal sealed class SetupForm:Form {
  static readonly Color Bg=Color.FromArgb(19,23,23),Panel=Color.FromArgb(28,34,33),Accent=Color.FromArgb(187,213,115),Ink=Color.FromArgb(230,235,224);
  readonly SetupProfile profile;readonly ComboBox gameList=new ComboBox();readonly Label gameStatus=new Label(),baseStatus=new Label(),fixStatus=new Label(),status=new Label();readonly Button install=new Button(),scan=new Button(),browseGame=new Button(),browseBase=new Button(),browseFix=new Button(),nexus=new Button(),findFix=new Button(),cancel=new Button(),steam=new Button(),elevate=new Button();readonly ProgressBar progress=new ProgressBar();
  string gameRoot="",baseArchive="",fixArchive="";bool busy,verified,awaitNexus,finished;int validation;CancellationTokenSource cancellation;
  internal SetupForm(SetupProfile p){profile=p;Text="Zone Spawner — мастер установки";BackColor=Bg;ForeColor=Ink;Font=new Font("Segoe UI",10);ClientSize=new Size(980,680);MinimumSize=new Size(960,720);StartPosition=FormStartPosition.CenterScreen;AutoScaleMode=AutoScaleMode.Dpi;
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=6,Padding=new Padding(20)};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));foreach(int h in new[]{75,150,110,155,70})layout.RowStyles.Add(new RowStyle(SizeType.Absolute,h));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(layout);
   var header=new Label{Dock=DockStyle.Fill,Text="УСТАНОВКА ZONE SPAWNER\n\n1. Найди игру   →   2. Подготовь UE4SS   →   3. Выбери фикс Nexus",ForeColor=Accent,Font=new Font("Segoe UI",12,FontStyle.Bold)};layout.Controls.Add(header,0,0);
   var game=Section("1. S.T.A.L.K.E.R. 2 в Steam",gameStatus);gameList.DropDownStyle=ComboBoxStyle.DropDownList;gameList.Width=510;gameList.AccessibleName="Найденная игра Steam";game.Controls.Add(gameList,0,1);var gameActions=Flow();Button(scan,"Найти в Steam",150);Button(browseGame,"Выбрать папку…",155);gameActions.Controls.Add(scan);gameActions.Controls.Add(browseGame);game.Controls.Add(gameActions,0,2);layout.Controls.Add(game,0,1);
   var engine=Section("2. UE4SS — experimental build 1028",baseStatus);engine.RowStyles[2].Height=0;var baseActions=Flow();baseActions.Controls.Add(new Label{Text="Скачается автоматически при установке; хеш будет проверен.",AutoSize=true,Padding=new Padding(0,8,12,0)});Button(browseBase,"Выбрать ZIP…",145);baseActions.Controls.Add(browseBase);engine.Controls.Add(baseActions,0,1);layout.Controls.Add(engine,0,2);
   var fix=Section("3. Фикс совместимости 1.2",fixStatus);var fixActions=Flow();Button(nexus,"Скачать фикс с Nexus",220);Button(findFix,"Найти скачанный ZIP",195);Button(browseFix,"Выбрать ZIP…",145);fixActions.Controls.Add(nexus);fixActions.Controls.Add(findFix);fixActions.Controls.Add(browseFix);fix.Controls.Add(fixActions,0,1);fix.Controls.Add(new Label{Text="На Nexus выбери «STALKER2 UE4SS Update2.0.5 Compatibility Fix V1.2».\nВход выполняется в браузере. После скачивания вернись сюда — мастер проверит ZIP.",Dock=DockStyle.Fill,ForeColor=Color.Silver},0,2);layout.Controls.Add(fix,0,3);
   status.Text="Распакуй пакет в постоянную папку. После установки её нельзя перемещать.";status.Dock=DockStyle.Fill;status.ForeColor=Accent;layout.Controls.Add(status,0,4);
   var bottom=Flow();Button(install,"Установить",160);install.BackColor=Accent;install.ForeColor=Bg;Button(cancel,"Отмена",110);Button(steam,"Запустить игру",160);Button(elevate,"Перезапустить от администратора",310);bottom.Controls.Add(install);bottom.Controls.Add(cancel);bottom.Controls.Add(steam);bottom.Controls.Add(elevate);steam.Visible=false;elevate.Visible=false;progress.Width=170;progress.Style=ProgressBarStyle.Marquee;progress.Visible=false;bottom.Controls.Add(progress);layout.Controls.Add(bottom,0,5);
   scan.Click+=async(s,e)=>await Scan();browseGame.Click+=(s,e)=>{using(var dialog=new FolderBrowserDialog{Description="Выбери корневую папку S.T.A.L.K.E.R. 2 Heart of Chornobyl",ShowNewFolderButton=false})if(dialog.ShowDialog(this)==DialogResult.OK){gameRoot=dialog.SelectedPath;gameList.Items.Clear();gameList.Items.Add(new SteamGame{Root=gameRoot});gameList.SelectedIndex=0;}};
   gameList.SelectedIndexChanged+=async(s,e)=>{var item=gameList.SelectedItem as SteamGame;if(item!=null){gameRoot=item.Root;await ValidateGame();}};
   browseBase.Click+=async(s,e)=>{string file=ChooseZip();if(file!=null)await ChooseArchive(file,true);};browseFix.Click+=async(s,e)=>{string file=ChooseZip();if(file!=null)await ChooseArchive(file,false);};findFix.Click+=async(s,e)=>await FindArchives();
   nexus.Click+=(s,e)=>{awaitNexus=true;Process.Start(new ProcessStartInfo(SetupProfile.NexusUrl){UseShellExecute=true});};Activated+=async(s,e)=>{if(awaitNexus&&!busy){awaitNexus=false;await FindArchives();}};
   install.Click+=async(s,e)=>await Install();cancel.Click+=(s,e)=>{if(busy){cancellation.Cancel();status.Text="Отменяю подготовку; уже начатое копирование будет завершено или восстановлено.";}else Close();};steam.Click+=(s,e)=>{Process.Start(new ProcessStartInfo("steam://rungameid/1643320"){UseShellExecute=true});Close();};
   elevate.Click+=(s,e)=>{try{var start=new ProcessStartInfo(Path.Combine(profile.Package,"ZoneSpawner.Setup.exe")){UseShellExecute=true,Verb="runas",WorkingDirectory=profile.Package};Process.Start(start);Close();}catch(System.ComponentModel.Win32Exception){status.Text="Запуск с правами администратора отменён.";}};
   FormClosing+=(s,e)=>{if(busy){e.Cancel=true;cancellation.Cancel();status.Text="Дождись завершения отмены установки.";}};Shown+=async(s,e)=>{await Scan();await FindArchives();};ControlsState();
  }
  static FlowLayoutPanel Flow(){return new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,Padding=new Padding(0,3,0,0)};}
  static void Button(Button b,string text,int width){b.Text=text;b.Width=width;b.Height=34;b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderSize=0;b.BackColor=Color.FromArgb(49,59,46);b.ForeColor=Ink;b.Cursor=Cursors.Hand;}
  static TableLayoutPanel Section(string title,Label info){var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,BackColor=Panel,Padding=new Padding(10)};p.RowStyles.Add(new RowStyle(SizeType.Absolute,24));p.RowStyles.Add(new RowStyle(SizeType.Absolute,36));p.RowStyles.Add(new RowStyle(SizeType.Absolute,39));p.RowStyles.Add(new RowStyle(SizeType.Percent,100));var caption=new Label{Text=title,ForeColor=Accent,Dock=DockStyle.Fill,Font=new Font("Segoe UI",10,FontStyle.Bold)};p.Controls.Add(caption,0,0);info.Dock=DockStyle.Fill;info.AutoEllipsis=true;p.Controls.Add(info,0,3);return p;}
  void ControlsState(){foreach(var c in new Control[]{scan,browseGame,browseBase,browseFix,nexus,findFix,gameList})c.Enabled=!busy&&!finished;install.Enabled=!busy&&!finished&&verified&&!String.IsNullOrEmpty(fixArchive);cancel.Text=busy?"Отменить":"Закрыть";progress.Visible=busy;}
  async Task Scan(){if(busy)return;gameStatus.Text="Ищу библиотеки Steam…";var games=await Task.Run(()=>SteamDiscovery.Find());gameList.Items.Clear();foreach(var g in games)gameList.Items.Add(g);if(games.Count>0)gameList.SelectedIndex=0;else{gameRoot="";verified=false;gameStatus.Text="Игра не найдена. Выбери её корневую папку вручную.";ControlsState();}}
  async Task ValidateGame(){int request=++validation;string chosen=gameRoot;verified=false;ControlsState();gameStatus.Text="Проверяю исполняемый файл игры…";try{await Task.Run(()=>SetupCore.VerifyGame(profile,chosen,true));if(request!=validation)return;verified=true;gameStatus.Text="✓ Найдена подходящая сборка. Игра должна оставаться закрытой.";gameStatus.ForeColor=Accent;}catch(Exception e){if(request!=validation)return;gameStatus.Text=e.Message;gameStatus.ForeColor=Color.FromArgb(243,157,130);}ControlsState();}
  string ChooseZip(){using(var dialog=new OpenFileDialog{Filter="ZIP-архив (*.zip)|*.zip",CheckFileExists=true,InitialDirectory=SteamDiscovery.Downloads()})return dialog.ShowDialog(this)==DialogResult.OK?dialog.FileName:null;}
  async Task ChooseArchive(string file,bool original){var label=original?baseStatus:fixStatus;label.Text="Проверяю архив…";try{bool valid=await Task.Run(()=>SetupCore.Matches(file,original?profile.BaseHash:profile.FixHash));if(!valid)throw new IOException(original?"Нужен точный UE4SS build 1028. Этот ZIP не подходит.":"Нужен фикс 1.2. Этот ZIP не подходит.");
    try{Directory.CreateDirectory(SetupCore.Cache);string cached=Path.Combine(SetupCore.Cache,original?"UE4SS_v3.0.1-1028-gd7e7826d.zip":"UE4SS-compatibility-fix-1.2.zip");if(!String.Equals(Path.GetFullPath(file),cached,StringComparison.OrdinalIgnoreCase))await Task.Run(()=>File.Copy(file,cached,true));file=cached;}catch(IOException){}catch(UnauthorizedAccessException){}
    if(original)baseArchive=file;else fixArchive=file;label.ForeColor=Accent;label.Text=original?"✓ UE4SS build 1028 найден и проверен":"✓ Фикс 1.2 найден и проверен";
   }catch(Exception e){if(original)baseArchive="";else fixArchive="";label.ForeColor=Color.FromArgb(243,157,130);label.Text=e.Message;}ControlsState();}
  async Task FindArchives(){if(busy)return;var folders=new[]{SetupCore.Cache,Path.Combine(profile.Package,"dependencies"),SteamDiscovery.Downloads()};baseStatus.Text="Проверяю кеш и папку загрузок…";fixStatus.Text="Ищу скачанный фикс 1.2…";var found=await Task.Run(()=>new[]{SetupCore.FindArchive(profile.BaseHash,folders),SetupCore.FindArchive(profile.FixHash,folders)});if(found[0]!=null)await ChooseArchive(found[0],true);else baseStatus.Text=String.IsNullOrEmpty(baseArchive)?"UE4SS будет скачан с официального GitHub.":"✓ UE4SS build 1028 найден и проверен";if(found[1]!=null)await ChooseArchive(found[1],false);else fixStatus.Text=String.IsNullOrEmpty(fixArchive)?"Скачай фикс с Nexus или выбери уже скачанный ZIP.":"✓ Фикс 1.2 найден и проверен";ControlsState();}
  void Report(string text){if(!IsDisposed)BeginInvoke((Action)(()=>status.Text=text));}
  async Task Install(){if(busy||!verified)return;busy=true;cancellation=new CancellationTokenSource();ControlsState();elevate.Visible=false;try{string chosen=gameRoot,original=baseArchive,fix=fixArchive;await Task.Run(()=>SetupCore.VerifyGame(profile,chosen,true));if(String.IsNullOrEmpty(original)){original=await SetupCore.DownloadBase(SetupCore.Cache,Report,cancellation.Token);baseArchive=original;baseStatus.Text="✓ UE4SS скачан и проверен";}await Task.Run(()=>SetupCore.Install(profile,chosen,original,fix,Report,cancellation.Token));finished=true;steam.Visible=true;status.Text="Установка завершена. Запусти игру, загрузи сохранение и нажми Ctrl + Alt + S.";}
   catch(OperationCanceledException){status.Text="Установка отменена.";}
   catch(UnauthorizedAccessException){status.Text="Недостаточно прав для выбранной папки. Перезапусти мастер от администратора и подтверди запрос Windows.";elevate.Visible=true;}
   catch(Exception e){status.Text=e.Message;}
   finally{busy=false;cancellation.Dispose();cancellation=null;ControlsState();}
  }
 }
}
